import{_ as n,o as i,c as r,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Versionsgeschichte und neuere Releases finden","description":"","frontmatter":{"title":"Versionsgeschichte und neuere Releases finden","source_pageid":1530,"source_revision":6389},"headers":[],"relativePath":"schild3/schueler/versionsgeschichte-von-schild-nrw.md","filePath":"schild3/schueler/versionsgeschichte-von-schild-nrw.md"}'),l={name:"schild3/schueler/versionsgeschichte-von-schild-nrw.md"};function a(u,e,s,h,o,d){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="versionsgeschichte-und-neuere-releases-finden" tabindex="-1">Versionsgeschichte und neuere Releases finden <a class="header-anchor" href="#versionsgeschichte-und-neuere-releases-finden" aria-label="Permalink to &quot;Versionsgeschichte und neuere Releases finden&quot;">​</a></h1><p>Finden Sie den Release-Bereich auf GitHub und die übernommenen Hinweise zu früheren Versionen. Neuere Veröffentlichungen werden im verlinkten Release-Bereich gepflegt.</p><h2 id="neuere-versionsgeschichte-nur-noch-in-github" tabindex="-1">Neuere Versionsgeschichte nur noch in GitHub <a class="header-anchor" href="#neuere-versionsgeschichte-nur-noch-in-github" aria-label="Permalink to &quot;Neuere Versionsgeschichte nur noch in GitHub&quot;">​</a></h2><p>Mit dem Release von SchILD-NRW 3 werden sowohl die Installationsdateien als auch die Versionsgeschichte ausschließlich im <a href="https://github.com/SVWS-NRW/Schild-NRW-3/releases" target="_blank" rel="noreferrer">Release-Bereich auf GitHub</a> gepflegt.</p><h2 id="v3-1-20-vom-31-10-2025-release" tabindex="-1">v3.1.20 vom 31.10.2025 - RELEASE <a class="header-anchor" href="#v3-1-20-vom-31-10-2025-release" aria-label="Permalink to &quot;v3.1.20 vom 31.10.2025 - RELEASE&quot;">​</a></h2><ul><li>Release Version</li><li>Neues Login-Fenster</li><li>Schnittstellenimport: Wenn bei den Basisdaten keine Klasse eingetragen war, wurde die betreffende Person beim Import weiterer Daten nicht gefunden. Nun behoben.</li><li>Fehlermeldung bei &quot;Daten gemäß Löschfristen löschen&quot; behoben.</li><li>Bei der Datenquelle KursSchueler wird jetzt auch die Collation berücksichtigt (Sortierung)</li><li>Abfrage für Datenquelle KursSchueler korrigiert</li><li>Bei den SMTP-Einstellungen gibt es jetzt eine weitere Option &quot;Konfiguration automatisch anpassen&quot;. Wenn diese aktiviert ist, werden möglicherweise widersprüchliche SMTP-Einstellungen automatisch korrigiert. Das war bisher implizit der Fall. Dieses Verhalten kann nun deaktiviert werden.</li><li>Es wird jetzt standardmäßig ein &quot;KeepConnectionAliveInterval&quot; von 10 Minuten verwendet. Das kann über einen Eintrag in der Datei Admin.ini aber auch geändert werden.</li><li>Lauffähig mit SVWS-Server v1.1.1</li><li>Wichtig!</li></ul><p>Die Report Basissammlung wurde mit Version 1.0.0 aktualisiert. Bei einem Update werden diese aber nicht ausgetauscht. Nur bei einer Neuinstallation! Diese können aber manuell hier heruntergeladen werden:</p><p><a href="https://github.com/SVWS-NRW/Schild-NRW-3-Reports/releases" target="_blank" rel="noreferrer">https://github.com/SVWS-NRW/Schild-NRW-3-Reports/releases</a></p><h2 id="v3-1-18-vom-26-09-2025" tabindex="-1">v3.1.18 vom 26.09.2025 <a class="header-anchor" href="#v3-1-18-vom-26-09-2025" aria-label="Permalink to &quot;v3.1.18 vom 26.09.2025&quot;">​</a></h2><ul><li>Anpassungen an die Version 1.0.12 des SVWS-Servers</li><li>Filterung auf Sonderpädagogen umgesetzt</li><li>Verwaltung der Lehrer-Lehrbefähigungen komplett auf SVWS-Server-API umgestellt.</li><li>Bei der Abschlussberechnung an der Gesamtschule können jetzt auch die Quartalsnoten ausgewählt werden.</li><li>BK und WBKs: In Das Feld &quot;Beruf&quot; kann nun auch ein Freitext eingegeben werden.</li><li>Auf dem Karteireiter &quot;Schulbesuch&quot; werden die Abschlüsse an der Herkunftsschule nun entsprechend dem Entlassdatum gefiltert.</li><li>Bei Neueingaben wurde manchmal das falsche Schuljahr/Halbjahr eingetragen, nun behoben.</li><li>Beim Gruppenprozess für die Versetzungs-/Abschlussberechnung an der Gesamtschule (und allen Schulformen, wo eine Quartalsprognose möglich ist) erscheint nun ein Dialog, wo man festlegen kann, welche Noten (Quartals- oder Zeugnisnoten) verwendet werden sollen</li><li>Bei den Lehrer-Lehrämtern wurde testweise mal die Option freigeschaltet, neue Datensätze auch ohne Verwendung der &quot;Plus&quot;-Schalters anzulegen</li><li>Bei Filterung auf einen Status wurde der Button zum Ausführen der Filterung nicht angezeigt, nun behoben.</li><li>Filterung der Abschlüsse auf dem Karteireiter &quot;Schulbesuch&quot; wurde überarbeitet</li><li>Beim Start wird nun geprüft, ob die Tabelle &quot;Schuljahresabschnitte&quot; korrekt ist. Folgendes wird geprüft: Mehrfacheinträge, Lücken, falsche Reihenfolge</li><li>Vor dem Löschen einer Klasse wird geprüft, ob darin SuS enthalten sind. Sollte dies der Fall sein, ist ein Löschen nicht möglich.</li><li>Man kann nun ein Zeitintervall für ein Ping zum Datenbankserver definieren. Dadurch kann verhindert werden, dass die Datenbankverbindung nach einer gewissen Zeit der Untätigkeit vom Datenbanktreiber gekappt wird.</li></ul><p>Dazu in der Datei &quot;Admin.ini&quot; (im Programmverzeichnis) den folgenden Eintrag machen (der Wert ist der Zeitabstand in Minuten)</p><p><code>[Administration]</code></p><p><code>KeepConnectionAliveInterval=5</code></p><ul><li>Beim Gruppenprozess für die Versetzungs-/Abschlussberechnung an der Gesamtschule (und allen Schulformen, wo eine Quartalsprognose möglich ist) erscheint nun ein Dialog, wo man festlegen kann, welche Noten (Quartals- oder Zeugnisnoten) verwendet werden sollen.</li><li>Bei den Lehrer-Lehrämtern wurde testweise mal die Option freigeschaltet, neue Datensätze auch ohne Verwendung der &quot;Plus&quot;-Schalters anzulegen.</li><li>Bei Filterung auf einen Status wurde der Button zum Ausführen der Filterung nicht angezeigt, nun behoben.</li><li>Anpassung an Version 1.0.11 des SVWS-Servers</li><li>Filterung der Abschlüsse auf dem Karteireiter &quot;Schulbesuch&quot; wurde überarbeitet</li><li>Beim Start wird nun geprüft, ob die Tabelle &quot;Schuljahresabschnitte&quot; korrekt ist. Folgendes wird geprüft: Mehrfacheinträge, Lücken, falsche Reihenfolge</li><li>Vor dem Löschen einer Klasse wird geprüft, ob darin SuS enthalten sind. Sollte dies der Fall sein, ist ein Löschen nicht möglich.</li><li>Bei der Kursart &quot;PUT&quot; wurde die &quot;Statistik-Nummer&quot; als &quot;0&quot; anstelle &quot;00&quot; gespeichert, nun behoben</li><li>Bei Grundschulen ist es wieder möglich, Quartalsnoten zu aktivieren</li><li>Die GeR-Berechnung bei der dritter Fremdsprache in Sek1 war nicht korrekt, nun behoben</li><li>Die Suche in der aktuellen Schülerauswahl wurde überarbeitet. Sie arbeitet nun auch dann flüssig, wenn der Karteireiter &quot;Akt. Halbjahr&quot; ausgewählt ist. Um die Suche nach Eingabe des Suchtextes zu aktivieren, muss die Eingabetaste gedrückt werden.</li><li>Die Anzeige und Eingabe von Straße, Hausnummer und Hausnr.-Zusatz erfolgt nun (wie beim Web-Client) zusammen in einem Eingabefeld. Beim Speichern werden daraus drei separate Werte für den Straßennamen, die Hausnummer und den Hausnr.-Zusatz ermittelt und in den zugehörigen Feldern der Datenbank abgelegt.</li><li>Bei Kursen, die schon belegt sind, ist keine Jahrgangsänderung mehr möglich, da dies zu Inkonsistenzen führen würde (der Jahrgang bei den SuS ist dann ein anderer als der beim Kurs), die dann wieder zu Probleme beim Abschnittswechsel führen würden. Wenn der Jahrgangsbezug eines schon belegten Kurses geändert werden muss, so ist der Kurs zu löschen und mit neuem Jahrgangsbezug neu anzulegen).</li><li>Die Filterung der Kurse nach einer Neueingabe eines Kurses wurde überarbeitet.</li><li>Bei der Report-Datenquelle &quot;KursSchueler&quot; können nun folgende Sortieroptionen gewählt werden:</li><li>Status, Name, Vorname</li><li>Status, Schulnr., Name, Vorname</li><li>Klasse, Name, Vorname</li><li>Name, Vorname</li><li>In der Report-Datenquelle &quot;Kurse&quot; steht jetzt auch ein Feld &quot;FachBezeichnung&quot; (ausgeschriebener Name des Faches)</li><li>Bei der Versendung einer Kursliste als Serienmail (an die Kursleitung) wird der Name der PDF-Datei nun wie folgt gebildet:</li></ul><p>Kurs_Jahrgang_Fach_Kursart_Kursleitung_Datum_KursID.pdf</p><p>Beispiel: L-1_10_L7_WPIGY_Kieß_2025-09-12_1649.pdf</p><ul><li>Die Zeilenhöhe in dem Fenster, in dem die Statistikfehler angezeigt werden, kann nun angepasst werden (um den Fehlertext komplett lesen zu können).</li><li>Die Berechtigungen für den &quot;Text-/Excel-Export&quot; und für den &quot;BAN-Export&quot; waren falsch gesetzt, nun behoben.</li><li>Beim WBK waren die Texte &quot;Semesterwechsel (in Sommersemester)&quot; und &quot;Semesterwechsel (in Wintersemester)&quot; vertauscht, nun korrigiert.</li><li>Beim E-Mail-Versand über SMTP konnten die Parameter &quot;Benutzername&quot; und &quot;Kennwort&quot; unter bestimmten Bedingungen nicht eingetragen werden. Das funktioniert jetzt wieder.</li><li>Beim Menüpunkt &quot;Info&quot; wird jetzt auch die Version des SVWS-Servers ausgegeben</li><li>Beim Gruppenprozess &quot;Eingabe der Prüfungsergebnisse zum Abitur&quot; wurde die Sortierung nicht immer korrekt ausgeführt, nun behoben.</li><li>Lauffähig mit dem SVWS-Server 1.0.12.</li><li>Datenbankrevision 47</li></ul><h2 id="v3-1-17-vom-29-08-2025" tabindex="-1">v3.1.17 vom 29.08.2025 <a class="header-anchor" href="#v3-1-17-vom-29-08-2025" aria-label="Permalink to &quot;v3.1.17 vom 29.08.2025&quot;">​</a></h2><ul><li>Filterung auf Sonderpädagoge umgesetzt</li><li>Verwaltung der Lehrer-Lehrbefähigungen komplett auf SVWS-Server-API umgestellt.</li><li>Bei der Abschlussberechnung an der Gesamtschule können jetzt auch die Quartalsnoten ausgewählt werden.</li><li>BK und WBKs: In Das Feld &quot;Beruf&quot; kann nun auch ein Freitext eingegeben werden.</li><li>Auf dem Karteireiter &quot;Schulbesuch&quot; werden die Abschlüsse an der Herkunftsschule nun entsprechend dem Entlassdatum gefiltert.</li><li>Bei Neueingaben wurde manchmal das falsche Schuljahr/Halbjahr eingetragen, nun behoben.</li><li>Beim Gruppenprozess für die Versetzungs-/Abschlussberechnung an der Gesamtschule (und allen Schulformen, wo eine Quartalsprognose möglich ist) erscheint nun ein Dialog, wo man festlegen kann, welche Noten (Quartals- oder Zeugnisnoten) verwendet werden sollen.</li><li>Bei den Lehrer-Lehrämtern wurde testweise mal die Option freigeschaltet, neue Datensätze auch ohne Verwendung des &quot;Plus&quot;-Schalters anzulegen.</li><li>Bei Filterung auf einen Status wurde der Button zum Ausführen der Filterung nicht angezeigt, nun behoben.</li><li>Anpassung an Version 1.0.11 des SVWS-Servers</li><li>Filterung der Abschlüsse auf dem Karteireiter &quot;Schulbesuch&quot; wurde überarbeitet</li><li>Beim Start wird nun geprüft, ob die Tabelle &quot;Schuljahresabschnitte&quot; korrekt ist. Folgendes wird geprüft: Mehrfacheinträge, Lücken, falsche Reihenfolge</li><li>Vor dem Löschen einer Klasse wird geprüft, ob darin SuS enthalten sind. Sollte dies der Fall sein, ist ein Löschen nicht möglich.</li><li>Man kann nun wieder (wie bei SchILD2) ein Zeit-Intervall für ein Ping zum Datenbankserver definieren. Dadurch kann verhindert werden, dass die Datenbankverbindung nach einer gewissen Zeit der Untätigkeit vom Datenbanktreiber gekappt wird.</li><li>Dazu in der Datei &quot;&quot;Admin.ini&quot;&quot; den folgenden Eintrag machen (der Wert ist der Zeitabstand in Minuten)</li></ul><p><code>[Administration]</code></p><p><code>KeepConnectionAliveInterval=5</code></p><ul><li>Bei der Kursart &quot;PUT&quot; wurde die &quot;Statistik-Nummer&quot; als &quot;0&quot; anstelle &quot;00&quot; gespeichert, nun behoben</li><li>Bei Grundschulen ist es wieder möglich, Quartalsnoten zu aktivieren</li><li>Die GeR-Berechnung bei der dritter Fremdsprache in Sek1 war nicht korrekt, nun behoben</li><li>Die Suche in der aktuellen Schülerauswahl wurde überarbeitet. Sie arbeitet nun auch dann flüssig, wenn der Karteireiter &quot;Akt. Halbjahr&quot; ausgewählt ist. Um die Suche nach Eingabe des Suchtextes zu aktivieren, muss die Eingabetaste gedrückt werden.</li><li>Version SVWS-Server 1.0.11</li></ul><h2 id="v3-1-15-vom-27-07-2025" tabindex="-1">v3.1.15 vom 27.07.2025 <a class="header-anchor" href="#v3-1-15-vom-27-07-2025" aria-label="Permalink to &quot;v3.1.15 vom 27.07.2025&quot;">​</a></h2><ul><li>Anpassungen an die Version 1.0.10 des SVWS-Servers</li><li>Versetzungsberechnung nun auch für vergangene Abschnitte möglich</li><li>Versetzungsalgorithmen: Falls bei einem Fach keine Fachgruppe vom SVWS-Server geliefert wird, wird diese aus den Einstellungen beim jeweiligen Fach geholt</li><li>Excel-/Text-Export: Feldlänge für Staatsangehörigkeiten und Verkehrssprachen erweitert</li><li>GER-Berechnung überarbeitet</li><li>Fehler bei Eingabe von ZP10-Noten behoben</li><li>Gruppenprozess Abinoteneingabe: Lehrkraft bei Kursauswahl sichtbar</li><li>Anzeige Abiturmeldungen überarbeitet</li><li>Es erfolgt jetzt immer eine Berechnung des Abiturergebnisses (auch bei fehlenden Angaben, z.B. mdl. Noten)</li><li>Anpassung am Bildschirmauflösung überarbeitet</li><li>Fehler bei Filterung auf Abschlussoptionen behoben</li><li>Auswahl Referenzniveaus an Änderung im SVWS-Server angepasst</li><li>Katalog &quot;Klassen/Versetzungstabelle&quot;: Sternchen bei statistik-relevanten Feldern nun vorhanden</li><li>Schuljahreswechsel: Änderungen bei einzelnen SuS wurde nicht übernommen, nun korrigiert</li><li>ZP10-Export bei WBK überarbeitet</li><li>Filterung auf Vermerkarten überarbeitet</li><li>Gruppenweise Kurse zuweisen: Sortieroption für Schüler hinzugefügt</li><li>Bei den Versetzungsberechnungen wurde der Versetzungsvermerk nicht immer eingetragen, nun korrigiert. Wichtig: Der Versetzungsvermerk wird nur im 2. Hj. eingetragen (Ausnahme: WBK)</li><li>Auf dem Karteireiter &quot;Schulbesuch&quot; werden die Abschlüsse an der eigenen Schule nun entsprechend dem Entlassdatum gefiltert.</li><li>Bei mehrfacher Versendung von Report-Serienmails wurde die Signatur mehrfach ausgegeben, nun behoben.</li><li>Anlegen eines neuen Kurses ohne Lehrkraft führt zu Fehlermeldung, nun behoben</li><li>Neue Symbole für &quot;Filter ausführen&quot; und &quot;Filter aufheben&quot;.</li><li>Bei der gruppenweisen Zuweisung von Kursen gibt es nun die Möglichkeit, die Schüler entweder nach Jahrgang, Name und Klasse oder nach Jahrgang, Klasse und Name sortieren zu lassen.</li><li>Wenn der Karteireiter &quot;Aktuelles Halbjahr&quot; ausgewählt war und in der Schülerliste über das Eingabefeld &quot;Suche…&quot; ein Schüler gesucht wurde, so wurden die Abschnittsdaten des gefundenen Schülers nicht automatisch aktualisiert. Dies ist nun behoben. Wichtig: Die Suche erfolgt sequentiell. Das hat zur Folge, dass derzeit für jeden durchlaufenen Schüler auch die &quot;abhängigen Daten&quot; (z.B. Leistungsdaten) geladen werden (sofern man sich auf einem Karteireiter befindet, auf dem diese Daten angezeigt werden). Das hat dann zur Folge, dass die Suche um so länger dauert, je weiter unten ein Schüler in der Liste steht. Es wird aber nach einer besseren Lösung gesucht.</li></ul><h2 id="v3-1-14-vom-24-06-2025" tabindex="-1">v3.1.14 vom 24.06.2025 <a class="header-anchor" href="#v3-1-14-vom-24-06-2025" aria-label="Permalink to &quot;v3.1.14 vom 24.06.2025&quot;">​</a></h2><ul><li>Suche nach Erziehernamen verlor Focus, behoben</li><li>Rechteprüfung bei Teilleistungen angepasst</li><li>Datum bei Sprachprüfung nicht eingebbar, korrigiert</li><li>Fehler bei Abiturzulassung korrigiert (Prüfung auf Anzahl Grundkurse)</li><li>Kopieren von markierten Fächern korrigiert</li><li>Anpassung bei Planspielmodus für Prognoseberechnung</li><li>Sprachenfolge WBK: Jahrgänge ergänzt</li><li>Holen der Abiturdaten: Abitur-Jahr wird automatisch eingetragen</li><li>Berechtigung bei Lehrerbearbeitung überarbeitet</li><li>Anzeige ZP10-Reiter in WBK korrigiert</li><li>Scrollbox im Fächerkatalog ergänzt</li><li>Personengruppen: Bearbeitung und Reportausgabe überarbeitet/korrigiert</li><li>Gruppenprozesse für Teilleistungen nun auch für Grundschulen verwendbar</li><li>WBK: ZP10-Karteireiter auch für Jahrgänge S5 und S6 sichtbar</li><li>Bei Gruppenprozess &quot;Kurse zuweisen&quot; wurden bei der Kursartauswahl die &quot;allgemeinen Kursarten&quot; zur Verfügung gestellt. Es werden nun die &quot;schülerbezogenen Kursarten&quot; zur Verfügung gestellt.</li><li>BK: Gliederung B08, B09 und B10: Anpassung an Kursarten E, EWFA und EWF</li><li>Neuaufnahme von Schüler: Bei der Ermittlung der Klassen im Zielabschnitt wurde noch das Feld &quot;Sichtbar&quot; verwendet, das mit der Version 1.0.8 des SVW-Servers weggefallen ist.</li><li>Hochschreiben von Klassenlehrern: Wenn im Zielabschnitt schon bei einer Klasse Einträge für Klassenlehrer vorhanden sind, werden für diese Klasse keine KL hinzugefügt</li><li>Anzeige der Vorgänger- und Folgeklassen bei der Klassenbearbeitung überarbeitet</li><li>Weitere Optionen beim gruppenweisen Ändern von Versetzungsdaten im Rahmen des Schuljahreswechsels hinzugefügt (z.B. Prüfungsordnung)</li><li>Fehler beim Erzeugen der Notendateien behoben</li><li>Texte im Fenster für den Schuljahreswechsel/Halbjahreswechsel situations- und schulformbezogen angepasst</li><li>Bei Filterung auf Lehrkräfte mit Statistikfehlern kam es zu einer Fehlermeldung, nun behoben.</li><li>Bei der Neueingabe eines Schülers kam es zu einer Fehlermeldung, wenn gleichzeitig eine PLZ eingegeben wurde.</li><li>Teilleistungen können jetzt gruppenweise für eine Fach/Kursart-Kombination gelöscht werden (Gruppenprozess &quot;Teilleistungen fachbezogen löschen&quot;)</li><li>Datenquelle &quot;SchuelerAdressen&quot; testweise so konfiguriert, dass sie als Hauptdatenquelle in einem Serienbrief an Betriebe genutzt werden kann (mit DQ Schueler als UnterDQ)</li></ul><h2 id="v3-1-13-vom-03-03-2025" tabindex="-1">v3.1.13 vom 03.03.2025 <a class="header-anchor" href="#v3-1-13-vom-03-03-2025" aria-label="Permalink to &quot;v3.1.13 vom 03.03.2025&quot;">​</a></h2><ul><li>EP-Jahre bei GS-Versetzung angepasst</li><li>Fehler bei Filter auf &quot;Status&quot; bei SchILD3-Filterverfahren korrigiert</li><li>Zwei Fehler bei Versetzungen korrigiert</li><li>Import LehrkraefteSonderzeiten.dat korrigiert (es werden jetzt auch vorhandene Datensätze aktualisiert)</li><li>ZP10-Ansicht beim WBK korrigiert (Anpassung an neue Statistik-Jahrgänge)</li><li>Bei Schulen mit Primarstufe wird jetzt das EP-Jahr auch auf dem Karteireiter Individualdaten I&quot; angezeigt (rechts oben, nur Ansicht)</li><li>Gruppenprozess &quot;Schulbesuchsjahre berechnen&quot; ausgeblendet (Schulbesuchsjahre werden ja nicht mehr angezeigt)</li><li>Schnittstellen-Import von Lehrerdaten, bei Neuimport wurde Fehler &quot;MasernImpfnachweis&quot; behoben</li><li>Neue Felder in Datenquelle &quot;SchildUmgebung&quot; für verschiedene Formate von Schuljahr/Abschnitt</li></ul><h2 id="v3-1-12-vom-03-03-2025" tabindex="-1">v3.1.12 vom 03.03.2025 <a class="header-anchor" href="#v3-1-12-vom-03-03-2025" aria-label="Permalink to &quot;v3.1.12 vom 03.03.2025&quot;">​</a></h2><ul><li>BAN-Export ergänzt</li><li>Actions und Gruppenprozesse an Benutzerrechte angepasst (noch ausstehend: &quot;BK-Abschluss/ZP10&quot;)</li><li>Personen einer Personengruppen: Excel-Export über rechte Maustaste</li><li>Meister-Bafög und Online-Anmeldung mit &quot;-&quot; vorbelegt</li><li>Gesamtschule: Zuweisungen überarbeitet</li><li>Anzeige der bei Auswahl des Anmeldejahres gemachten Angaben (z.B. für Klasse) bei einem gerade im Insert-Modus befindlichen Schülerdatensatzes</li><li>Optionale StopWatch für Zeitprotokollierung</li><li>Korrektur Abschlussberechnung Gy.</li><li>Feld &quot;EPJahre&quot; aus Tabelle &quot;Schueler&quot; entfernt</li><li>EP-Jahre nun in Tabelle SchuelerLernabschnittsdaten und auf Karteireiter &quot;Akt. Halbjahr&quot;</li><li>Feld &quot;Schulbesuchsjahre&quot; auf Karteireiter &quot;Akt. Halbjahr&quot; ausgeblendet (fällt demnächst weg)</li><li>Filterung auf EPJahre (bei Grundschule) nun dort auf Karteireiter &quot;Lernabschnitt/Leistungsdaten&quot;</li><li>Feld EPJahre in Report-Datenquelle Lernabschnitte</li><li>Schulbesuchsjahre bei Gruppenprozess &quot;Individualdaten ändern&quot; ausgeblendet</li><li>EPJahre nun bei Gruppenprozess &quot;Individualdaten ändern&quot; auf Karteireiter &quot;Lernabschnitte&quot; (bei Grundschule)</li><li>Grundschulen: Jahrgangszuweisung bei Klassen angepasst</li><li>Feld &quot;Schulbesuchsjahre&quot; auf Karteireiter &quot;Individualdaten I&quot; ausgeblendet</li><li>Grundschuljahrgänge bei Floskeleingabe korrigiert</li><li>Katalog &quot;EP-Jahre&quot; auf API umgestellt (bei Lernabschnittsdaten, Gruppenprozess &quot;Individualdaten ändern&quot;, Schüler-Filter)</li><li>RAP-Funktion &quot;FilterLaufbahnJahr&quot; korrigiert</li><li>EP-Jahre bei Grundschulen in Auswahlliste für Schülercontainer</li><li>Gruppenprozess &quot;Versetzung/Übertragung ins neue Halbjahr oder Abschluss&quot; überarbeitet für den Fall, dass alle SuS in den Abschluss kommen (z.B. frühzeitige Ausschulung der Q2)</li><li>Datenquelle &quot;Schueler&quot; Feld &quot;JahrgangsKrz&quot; wird nun befüllt</li><li>Datenquelle &quot;Kursschueler_mit_Fotos&quot; korrigiert</li><li>Fehler bei Schuljahreswechsel behoben</li><li>Überschriften &quot;EP-Jahr&quot; angepasst</li><li>Bei Ausklappen des Kataloges für die EP-Jahre wird das Kürzel und der Klartext angezeigt</li><li>Schuljahreswechsel: Problem mit nicht vorhandenen oder unsichtbaren Folgeklassen behoben</li><li>Schüler-Abfrage angepasst, damit EPJahre korrekt erscheinen</li><li>Sichtbarkeit der EP-Jahre hängt nun davon ab, on Primarjahrgänge vorhanden sind</li><li>Feld &quot;Sichtbar&quot; in Tabelle &quot;Klassen&quot; entfernt</li><li>Neue Datenquelle &quot;LehrerDSVGOEinwilligungen&quot;</li><li>Neue berechnete Felder für die Reportausgabe in folgenden Datenquellen: Schueler, Schueler_der_Klasse, KursSchueler</li></ul><p><em>AlleVornamen</em></p><p><em>Rufname</em></p><p><em>NameAlleVornamen</em></p><p><em>NameRufname</em></p><p><em>AlleVornamenName</em></p><p><em>RufnameName</em></p><ul><li><em>istErsatzPflichtFS</em> bei Prüfung, ob ein Fach als Sprachprüfungsfach in Frage kommt, entfernt</li><li>EP-Jahre bei Schnittstellenimport angepasst</li><li>Versetzungsprozedur bei Grundschulen und weiteren Schulen mit Primarstufe (Primus) angepasst.</li><li>Mahnung bei Schnittstellenexport und -import berücksichtigt</li><li>Lauffähig mit dem SVWS-Server 1.0.7 und 1.0.8.</li></ul><h2 id="v3-1-11-vom-16-03-2025" tabindex="-1">v3.1.11 vom 16.03.2025 <a class="header-anchor" href="#v3-1-11-vom-16-03-2025" aria-label="Permalink to &quot;v3.1.11 vom 16.03.2025&quot;">​</a></h2><ul><li>Bugfixes</li><li>Lauffähig mit SVWS-Server 1.0.4.</li></ul><h2 id="v3-1-8-vom-07-02-2025" tabindex="-1">v3.1.8 vom 07.02.2025 <a class="header-anchor" href="#v3-1-8-vom-07-02-2025" aria-label="Permalink to &quot;v3.1.8 vom 07.02.2025&quot;">​</a></h2><ul><li>Farben wieder einstellbar</li><li>Bugfixes</li><li>Jahrgänge 01 und 02 in der Schulform GS eingeführt (neue Statistik)</li><li>Lauffähig mit SVWS-Server 1.0.4.</li></ul><h2 id="v-3-1-7-vom-27-01-2025" tabindex="-1">v 3.1.7 vom 27.01.2025 <a class="header-anchor" href="#v-3-1-7-vom-27-01-2025" aria-label="Permalink to &quot;v 3.1.7 vom 27.01.2025&quot;">​</a></h2><ul><li>Behebt noch einen Bug bei der Hochschulung, wenn Fächer mitgenommen werden.</li></ul><h2 id="v3-1-6-vom-24-01-2025" tabindex="-1">v3.1.6 vom 24.01.2025 <a class="header-anchor" href="#v3-1-6-vom-24-01-2025" aria-label="Permalink to &quot;v3.1.6 vom 24.01.2025&quot;">​</a></h2><ul><li>Bugfixes bei der Hochschulung</li><li>Bugfixing Auswahl</li><li>Lauffähig mit SVWS-Server 1.0.2 und 1.0.3.</li></ul><h2 id="v3-1-4-vom-17-01-2025" tabindex="-1">v3.1.4 vom 17.01.2025 <a class="header-anchor" href="#v3-1-4-vom-17-01-2025" aria-label="Permalink to &quot;v3.1.4 vom 17.01.2025&quot;">​</a></h2><ul><li>Beim Speichern von Textfeldern werden Leerzeichen am Anfang und Ende des Textes entfernt. Felder mit leerem Inhalt werden als NULL gespeichert</li><li>Diverse Issues aus Github bearbeitet</li><li>Lauffähig mit dem SVWS-Server 1.0.2</li></ul><h2 id="v3-1-3-vom-10-12-2024" tabindex="-1">v3.1.3 vom 10.12.2024 <a class="header-anchor" href="#v3-1-3-vom-10-12-2024" aria-label="Permalink to &quot;v3.1.3 vom 10.12.2024&quot;">​</a></h2><ul><li>Über den folgenden Eintrag in der Datei ADMIN.INI kann nun der Proxy eingetragen werden:</li></ul><p>[Proxy]</p><p>Server=</p><p>Port=</p><h2 id="v3-1-2-vom-09-12-2024" tabindex="-1">v3.1.2 vom 09.12.2024 <a class="header-anchor" href="#v3-1-2-vom-09-12-2024" aria-label="Permalink to &quot;v3.1.2 vom 09.12.2024&quot;">​</a></h2><ul><li>Die Benutzerverwaltung erfolgt nun auch über die API des SVWS-Servers.</li><li>Bugs wurden behoben</li><li>Die Versionskontrolle zwischen SVWS-Server und SchILD-NRW3 ist nun bidirektional.</li><li>unbenutzte Vorlagen wurden aus dem Installationsordner entfernt.</li><li>die aktuellen Reports aus der Basis-Sammlung wurden eingebunden.</li><li>Lauffähig mit SVWS-Server 1.0.2</li></ul><h2 id="version-3-1-0-vom-18-10-2024-erstveroffentlichung" tabindex="-1">Version 3.1.0 vom 18.10.2024 - Erstveröffentlichung <a class="header-anchor" href="#version-3-1-0-vom-18-10-2024-erstveroffentlichung" aria-label="Permalink to &quot;Version 3.1.0 vom 18.10.2024 - Erstveröffentlichung&quot;">​</a></h2><ul><li>Eine öffentliche Beta-Version steht zum Download auf der Homepage zur Verfügung:</li></ul><p><a href="https://www.svws.nrw.de/download/schild-nrw3" target="_blank" rel="noreferrer">https://www.svws.nrw.de/download/schild-nrw3</a></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Versionsgeschichte_von_SchILD-NRW" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6389.</p>',59)])])}const b=n(l,[["render",a]]);export{c as __pageData,b as default};
